// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('PressStart2P');

const { fontFamily } = loadFont();



export type EightBitProgressProps = Record<string, any>;

const EightBitProgress: React.FC<EightBitProgressProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 6,
  barPrimaryColor = "#39FF14",
  barBackgroundColor = "#1a2b1a",
  terminalTextColor = "#39FF14",
  loadingText = "LOADING SYSTEM",
  completionText = "Processing Complete",
  totalPixelBlocks = 20,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing calculations
  const totalFrames = fps * durationInSeconds;
  // 75% of the video is the loading phase, 25% is the completion hold
  const loadingEndFrame = Math.floor(totalFrames * 0.75);

  // Animation Logic
  const rawProgress = interpolate(frame, [0, loadingEndFrame], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Quantize progress to simulate choppy 8-bit loading
  const blocksFilled = Math.floor(rawProgress * totalPixelBlocks);
  const percentage = Math.floor(rawProgress * 100);

  const isComplete = frame >= loadingEndFrame;

  // Blinking cursor effect (toggles every 15 frames)
  const blink = Math.floor(frame / 15) % 2 === 0;

  // Responsive sizing baseline
  const s = Math.min(width, height);
  const barWidth = width * 0.65;
  const barHeight = s * 0.08;
  const borderThickness = Math.max(4, Math.floor(s * 0.008));
  const blockGap = Math.max(2, Math.floor(s * 0.005));
  const mainFontSize = Math.floor(s * 0.035);
  const subFontSize = Math.floor(s * 0.025);

  // Extracted uppercase conversion for retro feel
  const displayLoadingText = loadingText.toUpperCase();
  const displayCompletionText = completionText.toUpperCase();

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: barWidth,
          alignItems: "stretch",
        }}
      >
        {/* Terminal Header */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-end",
            marginBottom: s * 0.04,
            color: terminalTextColor,
            fontSize: mainFontSize,
            textShadow: `4px 4px 0px ${terminalTextColor}33`,
            transition: "none",
          }}
        >
          <span style={{ transition: "none" }}>
            {isComplete ? displayCompletionText : displayLoadingText}
            {!isComplete && blink ? "_" : ""}
          </span>
          <span style={{ transition: "none" }}>
            {isComplete ? "100%" : `${percentage}%`}
          </span>
        </div>

        {/* 8-Bit Progress Bar Container */}
        <div
          style={{
            width: "100%",
            height: barHeight,
            border: `${borderThickness}px solid ${terminalTextColor}`,
            padding: borderThickness,
            display: "flex",
            gap: blockGap,
            backgroundColor: barBackgroundColor,
            boxSizing: "border-box",
            boxShadow: `8px 8px 0px ${terminalTextColor}33`,
            transition: "none",
          }}
        >
          {/* Discrete Pixel Blocks */}
          {Array.from({ length: totalPixelBlocks }).map((_, i) => {
            const isActive = i < blocksFilled || isComplete;
            return (
              <div
                key={i}
                style={{
                  flex: 1,
                  backgroundColor: isActive ? barPrimaryColor : "transparent",
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* Blinking Footer Prompt */}
        <div
          style={{
            marginTop: s * 0.06,
            height: subFontSize,
            textAlign: "center",
            color: terminalTextColor,
            fontSize: subFontSize,
            opacity: isComplete && blink ? 1 : 0,
            textShadow: `3px 3px 0px ${terminalTextColor}33`,
            transition: "none",
          }}
        >
          SYSTEM READY_
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default EightBitProgress;